const conta = items[0].json;

function dinheiroMeta(valor) {
  if (valor === undefined || valor === null || valor === '') return 0;

  // A Meta geralmente retorna valores monetários em centavos.
  return Number(valor) / 100;
}

function statusConta(status) {
  const mapa = {
    1: 'Ativa',
    2: 'Desativada',
    3: 'Não liquidada',
    7: 'Pendente de revisão',
    8: 'Em período de carência',
    9: 'Pendente de fechamento',
    100: 'Pendente de validação',
    101: 'Desativada'
  };

  return mapa[status] || `Status ${status}`;
}

const limiteConta = dinheiroMeta(conta.spend_cap);
const valorGasto = dinheiroMeta(conta.amount_spent);
const saldoDisponivel = limiteConta > 0 ? limiteConta - valorGasto : null;
const saldoEmAberto = dinheiroMeta(conta.balance);

let alerta = '';
let acao = '';

if (limiteConta > 0 && saldoDisponivel <= 0) {
  alerta = 'Limite da conta atingido ou sem saldo disponível.';
  acao = 'Adicionar saldo ou aumentar o limite da conta antes que os anúncios parem.';
} else if (limiteConta > 0 && saldoDisponivel <= limiteConta * 0.2) {
  alerta = 'Saldo disponível abaixo de 20% do limite.';
  acao = 'Recarregar saldo ou revisar orçamento das campanhas.';
} else if (saldoEmAberto > 0) {
  alerta = 'Existe valor em aberto na conta.';
  acao = 'Verificar cobrança/pagamento no Gerenciador de Anúncios.';
} else {
  alerta = 'Conta sem alerta crítico de saldo.';
  acao = 'Manter monitoramento diário.';
}

return [
  {
    json: {
      conta_anuncio: conta.account_id || '',
      nome_conta: conta.name || '',
      moeda: conta.currency || 'BRL',
      status_conta: statusConta(conta.account_status),

      limite_conta: limiteConta,
      valor_gasto: valorGasto,
      saldo_disponivel_estimado: saldoDisponivel,
      saldo_em_aberto: saldoEmAberto,

      mensagem_envio:
`SALDO META ADS

Conta: ${conta.name || conta.account_id || 'não identificada'}
ID: ${conta.account_id || ''}
Moeda: ${conta.currency || 'BRL'}
Status: ${statusConta(conta.account_status)}

Limite da conta: ${limiteConta > 0 ? `R$ ${limiteConta.toFixed(2)}` : 'sem limite identificado'}
Valor gasto: R$ ${valorGasto.toFixed(2)}
Saldo disponível estimado: ${saldoDisponivel !== null ? `R$ ${saldoDisponivel.toFixed(2)}` : 'não identificado'}
Saldo/valor em aberto: R$ ${saldoEmAberto.toFixed(2)}

Alerta:
${alerta}

Ação recomendada:
${acao}`
    }
  }
];
